const form=document.getElementById("alimonyForm"),result=document.getElementById("result");form&&form.addEventListener("submit",t=>{t.preventDefault();const e=parseFloat(document.getElementById("debt").value)||0,s=parseFloat(document.getElementById("days").value)||0,a=parseFloat(document.getElementById("rate").value);if(e<=0||s<=0){result.innerHTML='<p style="margin:0;color:#c0392b">Введите сумму задолженности и количество дней.</p>';return}const n=e*(a/100)*s;result.innerHTML=`
      <div class="result-list">
        <div class="item"><span>Сумма задолженности</span><span class="val">${fmt(e)} ₽</span></div>
        <div class="item"><span>Дней просрочки</span><span class="val">${fmt(s)} дн.</span></div>
        <div class="item total"><span>Неустойка</span><span class="val">${fmt(n)} ₽</span></div>
      </div>
      <p class="hint" style="margin-top:14px">Ставка: ${a}% в день.</p>
    `});function fmt(t){return new Intl.NumberFormat("ru-RU",{maximumFractionDigits:2}).format(t)}
